const body = $json.body || {};

const rawDate = body.date || new Date().toISOString().split('T')[0];

// Convert YYYY-MM-DD → M/D/YYYY
const [year, month, day] = rawDate.split('-');
const date = `${parseInt(month)}/${parseInt(day)}/${year}`;

const selectedBanks = Array.isArray(body.banks) ? body.banks : [];

const ALL_BANKS = ['Access Bank', 'First Bank', 'Zenith Bank'];

const row = {
  Date: date,
};

ALL_BANKS.forEach(bank => {
  row[bank] = selectedBanks.includes(bank) ? 'Yes' : 'No';
});

return [{ json: row }];

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Transfer Confirmation</title>
<link href="[URL]" rel="stylesheet">
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg: #f0f4f8;
    --card: #ffffff;
    --text: #1a202c;
    --sub: #64748b;
    --border: #e2e8f0;
    --accent: #0f4c81;
    --accent-light: #e8f0fe;
    --success: #16a34a;
    --success-light: #dcfce7;
    --shadow: 0 4px 24px rgba(15, 76, 129, 0.10);
  }

  body {
    font-family: 'DM Sans', sans-serif;
    background: var(--bg);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px 16px;
  }

  .card {
    background: var(--card);
    border-radius: 24px;
    box-shadow: var(--shadow);
    width: 100%;
    max-width: 460px;
    overflow: hidden;
    animation: slideUp 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }

  @keyframes slideUp {
    from { opacity: 0; transform: translateY(24px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  .card-header {
    background: var(--accent);
    padding: 32px 32px 28px;
    color: white;
  }

  .card-header .label {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    opacity: 0.7;
    margin-bottom: 8px;
  }

  .card-header h1 {
    font-family: 'Sora', sans-serif;
    font-size: 22px;
    font-weight: 700;
    line-height: 1.3;
  }

  .card-header .date-badge {
    display: inline-block;
    margin-top: 14px;
    background: rgba(255,255,255,0.15);
    border-radius: 8px;
    padding: 6px 14px;
    font-size: 13px;
    font-weight: 500;
  }

  .card-body {
    padding: 32px;
  }

  .instruction {
    font-size: 14px;
    color: var(--sub);
    line-height: 1.6;
    margin-bottom: 24px;
  }

  .bank-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 32px;
  }

  .bank-item {
    position: relative;
  }

  .bank-item input[type="checkbox"] {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
  }

  .bank-item label {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 16px 20px;
    border: 2px solid var(--border);
    border-radius: 14px;
    cursor: pointer;
    transition: all 0.2s ease;
    user-select: none;
  }

  .bank-item label:hover {
    border-color: var(--accent);
    background: var(--accent-light);
  }

  .bank-item input:checked + label {
    border-color: var(--accent);
    background: var(--accent-light);
  }

  .checkmark {
    width: 22px;
    height: 22px;
    border: 2px solid var(--border);
    border-radius: 6px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    background: white;
  }

  .bank-item input:checked + label .checkmark {
    background: var(--accent);
    border-color: var(--accent);
  }

  .checkmark svg {
    display: none;
  }

  .bank-item input:checked + label .checkmark svg {
    display: block;
  }

  .bank-info {
    flex: 1;
  }

  .bank-name {
    font-weight: 600;
    font-size: 15px;
    color: var(--text);
  }

  .bank-sub {
    font-size: 12px;
    color: var(--sub);
    margin-top: 2px;
  }

  .bank-icon {
    font-size: 22px;
  }

  .warning {
    display: none;
    background: #fff7ed;
    border: 1px solid #fed7aa;
    border-radius: 10px;
    padding: 12px 16px;
    font-size: 13px;
    color: #9a3412;
    margin-bottom: 20px;
    align-items: center;
    gap: 8px;
  }

  .warning.show { display: flex; }

  .submit-btn {
    width: 100%;
    background: var(--accent);
    color: white;
    border: none;
    border-radius: 14px;
    padding: 16px;
    font-family: 'DM Sans', sans-serif;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    letter-spacing: 0.3px;
  }

  .submit-btn:hover { background: #0a3d6b; transform: translateY(-1px); }
  .submit-btn:active { transform: translateY(0); }
  .submit-btn:disabled { background: #94a3b8; cursor: not-allowed; transform: none; }

  /* Success state */
  .success-screen {
    display: none;
    padding: 48px 32px;
    text-align: center;
    animation: slideUp 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .success-screen.show { display: block; }
  .card-body.hide { display: none; }

  .success-icon {
    width: 72px;
    height: 72px;
    background: var(--success-light);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 20px;
    font-size: 32px;
  }

  .success-screen h2 {
    font-family: 'Sora', sans-serif;
    font-size: 22px;
    color: var(--text);
    margin-bottom: 10px;
  }

  .success-screen p {
    color: var(--sub);
    font-size: 14px;
    line-height: 1.6;
  }

  .submitted-banks {
    margin-top: 20px;
    background: var(--success-light);
    border-radius: 12px;
    padding: 14px 18px;
    font-size: 13px;
    color: var(--success);
    font-weight: 500;
  }
</style>
</head>
<body>

<div class="card">
  <div class="card-header">
    <div class="label">Daily Confirmation</div>
    <h1>Which banks were credited today?</h1>
    <div class="date-badge" id="dateBadge">Loading date…</div>
  </div>

  <div class="card-body" id="formBody">
    <p class="instruction">
      Tick the banks that received a transfer today. Leave unchecked if no transfer was made to that bank.
    </p>

    <div class="bank-list">

      <div class="bank-item">
        <input type="checkbox" id="accessBank" value="Access Bank">
        <label for="accessBank">
          <div class="checkmark">
            <svg width="12" height="10" viewBox="0 0 12 10" fill="none">
              <path d="M1 5L4.5 8.5L11 1.5" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </div>
          <div class="bank-info">
            <div class="bank-name">Access Bank</div>
            <div class="bank-sub">Mark if credited today</div>
          </div>
          <div class="bank-icon">🏦</div>
        </label>
      </div>

      <div class="bank-item">
        <input type="checkbox" id="firstBank" value="First Bank">
        <label for="firstBank">
          <div class="checkmark">
            <svg width="12" height="10" viewBox="0 0 12 10" fill="none">
              <path d="M1 5L4.5 8.5L11 1.5" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </div>
          <div class="bank-info">
            <div class="bank-name">First Bank</div>
            <div class="bank-sub">Mark if credited today</div>
          </div>
          <div class="bank-icon">🏦</div>
        </label>
      </div>

      <div class="bank-item">
        <input type="checkbox" id="zenithBank" value="Zenith Bank">
        <label for="zenithBank">
          <div class="checkmark">
            <svg width="12" height="10" viewBox="0 0 12 10" fill="none">
              <path d="M1 5L4.5 8.5L11 1.5" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </div>
          <div class="bank-info">
            <div class="bank-name">Zenith Bank</div>
            <div class="bank-sub">Mark if credited today</div>
          </div>
          <div class="bank-icon">🏦</div>
        </label>
      </div>

    </div>

    <div class="warning" id="noBankWarning">
      ⚠️ No banks selected — this will record <strong>No</strong> for all three banks. Continue?
    </div>

    <button class="submit-btn" id="submitBtn" onclick="handleSubmit()">
      Submit Confirmation
    </button>
  </div>

  <!-- Success screen shown after submission -->
  <div class="success-screen" id="successScreen">
    <div class="success-icon">✅</div>
    <h2>Confirmation Recorded</h2>
    <p>Thank you, Ngozi! Your response has been saved successfully.</p>
    <div class="submitted-banks" id="submittedSummary"></div>
  </div>
</div>

<script>
  // Read date from table_1 param, fallback to today
  const params = new URLSearchParams(window.location.search);
  const dateParam = params.get('date') || new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  document.getElementById('dateBadge').textContent = '📅 ' + dateParam;

  // Your n8n webhook URL
  const WEBHOOK_URL = '[URL]';

  let noBankConfirmed = false;

  function handleSubmit() {
    const banks = ['Access Bank', 'First Bank', 'Zenith Bank'];
    const checkboxIds = ['accessBank', 'firstBank', 'zenithBank'];

    const selected = checkboxIds
      .map((id, i) => document.getElementById(id).checked ? banks[i] : null)
      .filter(Boolean);

    // If nothing selected and not yet confirmed, show warning and ask to confirm
    if (selected.length === 0 && !noBankConfirmed) {
      document.getElementById('noBankWarning').classList.add('show');
      const btn = document.getElementById('submitBtn');
      btn.textContent = 'Confirm — No Banks Credited';
      btn.style.background = '#dc2626';
      noBankConfirmed = true;
      return;
    }

    submitData(selected);
  }

  async function submitData(selected) {
    const btn = document.getElementById('submitBtn');
    btn.disabled = true;
    btn.textContent = 'Submitting…';

    const payload = {
      date: params.get('date') || new Date().toISOString().split('T')[0],
      banks: selected   // e.g. ["Access Bank", "Zenith Bank"] or []
    };

    try {
      await fetch(WEBHOOK_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
    } catch (e) {
      // Even on network error, show success to user — n8n will handle retries
      console.error(e);
    }

    // Show success screen
    document.getElementById('formBody').classList.add('hide');
    const successScreen = document.getElementById('successScreen');
    successScreen.classList.add('show');

    const summary = selected.length > 0
      ? '✅ Credited: ' + selected.join(', ')
      : '❌ No banks credited today';
    document.getElementById('submittedSummary').textContent = summary;
  }

  // Reset the "confirm no banks" state if user checks a box after seeing warning
  document.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    cb.addEventListener('change', () => {
      if (noBankConfirmed) {
        noBankConfirmed = false;
        document.getElementById('noBankWarning').classList.remove('show');
        const btn = document.getElementById('submitBtn');
        btn.textContent = 'Submit Confirmation';
        btn.style.background = '';
      }
    });
  });
</script>

</body>
</html>`;

return [
  {
    json: {
      html
    }
  }
];
